export function results(root: string): CheckResult[] {
  const p = join(localDirectory(root), 'checks.json');
  return existsSync(p) ? readJson<CheckResult[]>(p) : [];
}
export function recordCheck(root: string, input: Omit<CheckResult, 'id' | 'recordedAt'>): CheckResult {
  if (!input || !nonempty(input.method) || !nonempty(input.environment) || !nonempty(input.evidence) ||
      !['pass', 'fail', 'inconclusive'].includes(input.outcome) || !Array.isArray(input.tests) ||
      !input.tests.every(t => nonempty(t.id) && ['pass', 'fail', 'inconclusive'].includes(t.outcome))) throw new Error('A check needs method, environment, evidence, outcome, and explicit individual test outcomes (or []).');
  if (new Set(input.tests.map(t => t.id)).size !== input.tests.length) throw new Error('A check may give each test one outcome.');
  if (!/^(?:[0-9a-f]{40}|[0-9a-f]{64})$/.test(input.tree) || git(root, ['cat-file', '-t', input.tree]).trim() !== 'tree') throw new Error('Check input must identify an existing Git tree.');
  const result = { ...input, id: randomUUID(), recordedAt: new Date().toISOString() };
  writeJson(join(localDirectory(root), 'checks.json'), [...results(root), result]);
  return result;
}

  const checks = input.resultIds.map(id => {
    const r = results(root).find(r => r.id === id);
    if (!r) throw new Error(`Missing recorded result: ${id}`);
    if (r.tree !== contentTree) throw new Error(`Result ${id} examined different content. Record checks for this exact snapshot.`);
    if (r.outcome !== 'pass' || r.tests.some(t => t.outcome !== 'pass')) throw new Error(`Result ${id} is not a passing check.`);
    return r;
  });
  if (!checks.length) throw new Error('Record at least one appropriate check, including a manual check when automated tests do not apply.');
  const review: Review & { unmapped: Input['unmapped'] } = {
    id, base, contentTree, reviewer: input.reviewer, summary: input.summary, examined: input.examined,
    unresolved: [], results: checks, recordedAt: new Date().toISOString(), unmapped: input.unmapped ?? [],
  };
  writeJson(pathInside(root, reviewPath), review);
  const finalTree = snapshot(root, [...paths, reviewPath], base);
  if (head(root) !== base || snapshot(root, paths, base) !== contentTree) throw new Error('Files or HEAD changed during preparation. Prepare again.');
  const state: Prepared = { id, base, contentTree, finalTree, paths, reviewPath, createdAt: new Date().toISOString() };
  writeJson(join(localDirectory(root), 'ready.json'), state);
  return { ...state, preparationMs: performance.now() - start };
}

  const equivalents = new Set([tree]);
  // Compare actual content, excluding only each review's own newly-added record.
  for (const { path, review } of history) {
    try {
      if (typeof review.base !== 'string' || typeof review.contentTree !== 'string' || !/^(?:[0-9a-f]{40}|[0-9a-f]{64})$/.test(review.base) || !/^(?:[0-9a-f]{40}|[0-9a-f]{64})$/.test(review.contentTree)) continue;
      if (git(root, ['diff', '--name-only', review.contentTree, tree]).trim() === path) equivalents.add(review.contentTree);
    } catch { /* An unavailable historical review is not current evidence. */ }
  }
  const checks = new Map<string, CheckResult>();
  for (const result of [...(revision === 'working' ? results(root) : []), ...history.flatMap(h => Array.isArray(h.review.results) ? h.review.results : [])]) {
    if (result && typeof result.id === 'string' && Array.isArray(result.tests)) checks.set(result.id, result);
  }
  const branches = git(root, ['log', '-12', '--format=%H%x09%s']).trim().split('\n').map(line => { const [id, ...title] = line.split('\t'); return { id, title: title.join('\t') }; });
  return { project, comparison: comparison(root, project, pending, history, tree), ready: pending, history: branches,
    dirty: !!git(root, ['status', '--porcelain']).trim(),
    checks: [...checks.values()].sort((a, b) => b.recordedAt.localeCompare(a.recordedAt)).map(r => ({ ...r, current: equivalents.has(r.tree) })) };
}

export interface CheckResult {
  id: string; tree: string; method: string; outcome: 'pass' | 'fail' | 'inconclusive';
  recordedAt: string; environment: string; evidence: string;
  tests: { id: string; outcome: 'pass' | 'fail' | 'inconclusive' }[];
}
export interface ReviewInput {
  reviewer: string; summary: string;
  examined: { id: string; outcome: 'revised' | 'unchanged'; reason: string }[];
  unresolved: string[]; resultIds: string[];
}
export interface Review extends Omit<ReviewInput, 'resultIds'> {
  id: string; base: string; contentTree: string; recordedAt: string; results: CheckResult[];
}
export interface Ready { id: string; base: string; contentTree: string; finalTree: string; paths: string[]; reviewPath: string; createdAt: string }
